from decimal import Decimal, ROUND_HALF_UP


def total_price(unit_price, quantity, tax_rate):
    subtotal = Decimal(str(unit_price)) * Decimal(str(quantity))
    total = subtotal * (Decimal(1) + Decimal(str(tax_rate)))
    return float(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))

def has_pair_with_sum(nums, target):
    seen = set()
    for num in nums:
        if target - num in seen:
            return True
        seen.add(num)
    return False

def pluralize(word, count):
    if count == 1:
        return word
    if word.endswith('y') and len(word) > 1 and word[-2].lower() not in 'aeiou':
        return word[:-1] + 'ies'
    if word.endswith(('s', 'x', 'ch', 'sh')):
        return word + 'es'
    return word + 's'

def dedupe_preserve_order(items):
    seen = set()
    result = []
    for item in items:
        key = item.strip().lower()
        if key not in seen:
            seen.add(key)
            result.append(item)
    return result
